    function handleImageLoadError(img){
      if(!img || img.dataset.fallbackApplied === "true") return;
      img.dataset.fallbackApplied = "true";
      img.classList.add("image-load-error");
      img.removeAttribute("data-zoom");
      img.alt = state.lang === "ja" ? "画像を読み込めません" : "Gambar tidak dapat dimuat";
      const svg = `<svg xmlns="http://www.w3.org/2000/svg" width="640" height="420" viewBox="0 0 640 420"><rect width="640" height="420" rx="32" fill="#f4efff"/><rect x="188" y="92" width="264" height="190" rx="24" fill="#ffffff" stroke="#d9ccff" stroke-width="6"/><circle cx="264" cy="158" r="25" fill="#bda8ff"/><path d="M214 250l74-69 52 47 35-30 57 52H214z" fill="#243B73" opacity=".78"/><text x="320" y="338" text-anchor="middle" font-family="Arial,sans-serif" font-size="25" font-weight="700" fill="#1B2F60">Gambar tidak tersedia</text></svg>`;
      img.src = "data:image/svg+xml;charset=UTF-8," + encodeURIComponent(svg);
    }
    document.addEventListener("error", event => {
      const target = event.target;
      if(target && target.tagName === "IMG") handleImageLoadError(target);
    }, true);

    async function initSupabase(){
      try {
        let status = await initializeSupabase({ensureParticipant:state.session?.role === "user"});
        if(!state.session && status.authenticated && !status.anonymous){
          await signOutWikaruAdmin();
          status = cloudStatus();
        }
        supabaseReady = Boolean(status.authenticated);
        document.dispatchEvent(new CustomEvent("wikaru:supabase-ready",{detail:status}));
        if(supabaseReady) setTimeout(()=>{ try { flushPendingResults(); } catch(_) {} },0);
      } catch (e) {
        supabaseReady = false;
        console.info("Wikaru berjalan dalam mode lokal:", e?.message || e);
        try { toast(t("localOnly")); } catch(_) {}
      }
      return supabaseReady;
    }

    function t(k){ return (labels[state.lang] && labels[state.lang][k]) || labels.id[k] || k; }
    function esc(s=""){ return String(s).replace(/[&<>"']/g,m=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#039;"}[m])); }
    function modeOptionLabel(mode, lang=state.lang){
      const map = {
        id:{study:"Belajar Santai", listening:"Dengar & Tebak", shadowing:"Shadowing", speed:"Tantangan Cepat"},
        ja:{study:"ゆっくり学習", listening:"聞いて当てる", shadowing:"シャドーイング", speed:"スピード挑戦"}
      };
      return (map[lang] || map.id)[mode] || mode;
    }
    function renderModeSelectOptions(){
      const sel = $("#modeSelect");
      if(!sel) return;
      const supportedModes = ["study","listening","shadowing","speed"];
      let storedMode = "study";
      try { storedMode = localStorage.getItem("wikaru_quiz_mode") || "study"; } catch(_) {}
      const keep = sel.value || storedMode;
      sel.innerHTML = supportedModes.map(v=>`<option value="${v}">${esc(modeOptionLabel(v))}</option>`).join("");
      sel.value = supportedModes.includes(keep) ? keep : "study";
      updateQuizModeHint(sel.value);
    }
    function cardCounterText(current,total,lang=state.lang){ return lang === "ja" ? `${current} / ${total} 枚` : `Kartu ${current} / ${total}`; }
    function progressTextLabel(percent,lang=state.lang){ return lang === "ja" ? `${percent}% 完了` : `${percent}% Selesai`; }
    function kkmStatusLabel(score,lang=state.lang){
      const passed = Number(score||0) >= KKM_SCORE;
      if(lang === "ja") return passed ? "合格基準を達成" : "合格基準に未達";
      return passed ? "Di atas KKM / Tuntas" : "Di bawah KKM / Belum Tuntas";
    }
    function kkmStatusClass(score){ return Number(score||0) >= KKM_SCORE ? "pass" : "fail"; }
    function extractMainJapaneseText(text=""){
      const raw = String(text || "").trim();
      if(!raw) return "";
      // Pertahankan seluruh bentuk kosakata sebagaimana data sumber,
      // termasuk tanda kurung （）, kurung siku ［］, ～, dan bentuk alternatif.
      return raw;
    }
    function detailMainJapaneseText(d={}){
      const displayTerm = String(d.displayTerm || "").trim();
      const main = extractMainJapaneseText(d.kanji || "");
      return displayTerm || main || String(d.kana || "").trim() || "-";
    }
    function jpText(v){
      return vocabMainText(v);
    }

    function vocabMainText(v={}){
      const displayTerm = String(v.displayTerm || "").trim();
      const kanji = extractMainJapaneseText(v.kanji || "");
      const kana = String(v.kana || "").trim();
      const romaji = String(v.romaji || "").trim();
      return displayTerm || kanji || kana || romaji || "-";
    }
    function vocabReadingText(v={}){
      const romaji = String(v.romaji || "").trim();
      const kana = String(v.kana || "").trim();

      return romaji || kana || "-";
    }
    function kanaScriptType(value=""){
      const text=String(value || "").trim();
      const hasHiragana=/[\u3040-\u309f]/u.test(text);
      const hasKatakana=/[\u30a0-\u30ff\uff65-\uff9f]/u.test(text);
      if(hasHiragana && !hasKatakana) return "hiragana";
      if(hasKatakana && !hasHiragana) return "katakana";
      if(hasHiragana || hasKatakana) return "mixed";
      return "none";
    }
    function katakanaToHiragana(value=""){
      return String(value || "").normalize("NFKC").replace(/[ァ-ヶ]/g,ch=>String.fromCharCode(ch.charCodeAt(0)-0x60));
    }
    function strictHiraganaText(v={}){
      const explicit=String(v.hiragana || v.furigana || "").trim();
      if(explicit) return katakanaToHiragana(explicit);
      const value=String(v.kana || "").trim();
      const type=kanaScriptType(value);
      if(type==="hiragana") return value;
      if(type==="katakana" || type==="mixed") return katakanaToHiragana(value);
      return "";
    }
    function readingKanaMeta(v={},lang=state.lang){
      const source=String(v.kana || "").trim();
      const sourceType=kanaScriptType(source);
      const value=strictHiraganaText(v) || source;
      const valueType=kanaScriptType(value);
      const label=valueType==="hiragana"
        ? (lang==="ja"?"ひらがな":"Hiragana")
        : (lang==="ja"?"かな":"Kana");
      return {value,type:valueType==="hiragana"?"hiragana":"mixed",label,sourceType,source};
    }
    function kanaDisplayMeta(v={},lang=state.lang){
      const value=String(v.kana || "").trim();
      const type=kanaScriptType(value);
      const labels={
        hiragana:lang==="ja"?"ひらがな":"Hiragana",
        katakana:lang==="ja"?"カタカナ":"Katakana",
        mixed:lang==="ja"?"かな":"Kana",
        none:lang==="ja"?"読み方":"Cara baca"
      };
      return {value,type,label:labels[type]||labels.none};
    }
    function getVocabSpeechText(v = {}) {
      let text = String(v.speech || v.speechText || v.kana || v.reading || v.furigana || jpText(v) || "").trim();
      text = text.replace(/[〜～]/g, "").trim();
      return text || String(jpText(v) || "").trim();
    }
    function speakVocab(v = {}) {
      const text = getVocabSpeechText(v);
      if(!text) return;
      return speak(text, "ja-JP");
    }
    function sentenceCaseUi(value=""){
      const text = String(value || "").replace(/（/g,"(").replace(/）/g,")").replace(/\s+/g," ").trim();
      return text.replace(/^([\s“”‘’'"(\[]*)([a-zà-öø-ÿ])/u,(_,prefix,letter)=>prefix+letter.toLocaleUpperCase("id-ID"));
    }
    function cleanIndo(v){ return String(v.indonesia || "").trim(); }
    function fictionExplanation(v={}){
      const text = [v.indonesia, v.kanji, v.kana, v.romaji, v.typeCategory, v.sectionCategory].filter(Boolean).join(" ").toLowerCase();
      if(/大学|daigaku|universitas|sekolah|kampus|gakkou|学校/.test(text)) return "nama sekolah/universitas rekaan";
      if(/病院|byouin|rumah sakit|hospital/.test(text)) return "nama tempat rekaan";
      if(/perusahaan|organisasi|company|denki|air|akc|imc|電気/.test(text)) return "nama perusahaan/organisasi rekaan";
      if(/さん|nama orang|orang/.test(text)) return "nama orang rekaan";
      if(/tempat|kota|daerah|国|kuni/.test(text)) return "nama tempat rekaan";
      return "contoh rekaan";
    }
    function formatIndonesianMeaning(v={}){
      // Teks arti dipertahankan persis seperti data sumber, termasuk tanda baca.
      return String(v.indonesia || "").trim();
    }
    function formatQuizIndonesianMeaning(v={}){
      // Kuis menampilkan arti yang sama persis dengan data materi.
      return String(v.indonesia || "").trim();
    }
    function formatDetailIndonesianMeaning(d={}){
      // Riwayat/detail mempertahankan kurung, kurung siku, koma, titik dua, garis miring, ～, dan tanda lain.
      return String(d.indonesia || "").trim();
    }
    function hasFictionVocabulary(list){ return (list || []).some(v=>isFictionVocab(v)); }
    function isFictionVocab(v={}){
      const direct = v.isFiction === true || v.fiction === true || v.is_fiction === true;
      const meta = [v.label, v.labels, v.tag, v.tags, v.category, v.kategori, v.typeCategory, v.sectionCategory, v.indonesia]
        .flat().filter(Boolean).join(" ").toLowerCase();
      return direct || /(^|\s|[,;|/])fiksi($|\s|[,;|/])/.test(meta);
    }
