    function bab27GroupedCardHtml(v){
      const fav = state.favorites.includes(v.id);
      const meaning = formatIndonesianMeaning(v);
      const mainText = String(vocabMainText(v) || "").trim();
      const kanaText = strictHiraganaText(v);
      const kanaSourceType = kanaScriptType(v.kana || "");
      const romajiText = String(vocabReadingText(v) || "").trim();
      const showKana = Boolean(kanaText && kanaText !== mainText);
      const thumb = v.image ? `<img class="thumb" src="${esc(v.image)}" alt="${esc(v.imageAlt || mainText)}" loading="lazy" data-zoom="${esc(v.image)}" decoding="async">` : `<span class="thumb-placeholder"><i class="fa-regular fa-image"></i></span>`;
      const sequence = Math.max(1, BAB27_REFERENCE_INFO_VOCABULARY.findIndex(item=>item.id===v.id)+1);
      return `<article class="vocab-card">
        <span class="bab27-card-number" aria-label="Nomor kosakata ${sequence}">${String(sequence).padStart(2,"0")}</span>
        <div class="vocab-top">
          ${thumb}
          <div class="vocab-script-block">
            <div class="vocab-jp jp">${esc(mainText)}</div>
            <div class="vocab-reading-stack">
              ${showKana ? `<div class="vocab-kana jp" data-reading-source="${esc(kanaSourceType)}" aria-label="${state.lang === "ja" ? "ひらがなの読み方" : "Cara baca hiragana"}">${esc(kanaText)}</div>` : ""}
              <div class="vocab-romaji">${esc(romajiText)}</div>
            </div>
          </div>
        </div>
        <div class="vocab-id">${esc(meaning)}</div>
        <div class="tag-row"><span class="tag">${esc(v.chapter)}</span><span class="tag green">${esc(categoryLabel(v.typeCategory,"type"))}</span><span class="tag pink">${esc(categoryLabel(v.sectionCategory,"section"))}</span></div>
        <div class="card-actions"><button type="button" class="icon-btn" data-speak-id="${esc(v.id)}" title="${state.lang==="ja"?"聞く":"Dengar"}" aria-label="${state.lang==="ja"?"語彙を聞く":"Dengarkan kosakata"}"><i class="fa-solid fa-volume-high"></i></button><button type="button" class="icon-btn ${fav?"active":""}" data-fav="${v.id}" title="${state.lang==="ja"?"お気に入り":"Favorit"}" aria-label="${state.lang==="ja"?"お気に入りを切り替える":"Ubah status favorit"}"><i class="${fav?"fa-solid":"fa-regular"} fa-star"></i></button><button type="button" class="icon-btn" data-note-material="${esc(v.id)}" title="${state.lang==="ja"?"メモ":"Catatan"}" aria-label="${state.lang==="ja"?"詳細とメモを開く":"Buka detail dan catatan"}"><i class="fa-regular fa-note-sticky"></i></button><button type="button" class="icon-btn" data-example-material="${esc(v.id)}" title="${state.lang==="ja"?"例文":"Contoh kalimat"}" aria-label="${state.lang==="ja"?"例文を開く":"Buka contoh kalimat"}"><i class="fa-regular fa-comment-dots"></i></button></div>
      </article>`;
    }

