    function bab35NormalizeSituation(value=""){
      return String(value || "")
        .toLowerCase()
        .normalize("NFD")
        .replace(/[\u0300-\u036f]/g, "")
        .replace(/[-–—.,!?;:'"()[\]{}\\/|@#$%^&*_+=~`<>、。！？「」『』（）・]/g, " ")
        .replace(/\s+/g, " ")
        .trim();
    }

    function bab35KotowazaCorpus(){
      const fromImage = BAB35_REFERENCE_KOTOWAZA_ITEMS.map(item=>({
        id:item.id,
        ja:item.kanji || item.displayTerm,
        display:item.displayTerm,
        kana:item.kana,
        romaji:item.romaji,
        idn:item.indonesia,
        meaning:item.explanation,
        situation:item.situation,
        keywords:item.keywords || [],
        expressionType:"Kotowaza Bab 35",
        source:"Bab 35"
      }));
      const related = BAB35_RELATED_KOTOWAZA.map(item=>({...item,display:item.ja,expressionType:"Kotowaza",source:"Tambahan"}));
      const bridge = BAB35_SITUATION_EXPRESSION_BRIDGE.map(item=>({...item,display:item.ja,source:"Konteks tambahan"}));
      return [...fromImage, ...related, ...bridge];
    }

    function bab35RankKotowaza(query){
      const q = bab35NormalizeSituation(query);
      if(!q) return [];
      const tokens = q.split(" ").filter(token=>token.length >= 3);
      return bab35KotowazaCorpus().map((item,index)=>{
        const keywords = (item.keywords || []).map(bab35NormalizeSituation);
        const haystack = bab35NormalizeSituation([item.ja,item.display,item.kana,item.romaji,item.idn,item.meaning,item.situation,...keywords].join(" "));
        let score = 0;
        if(haystack.includes(q)) score += 30;
        keywords.forEach(keyword=>{
          if(!keyword) return;
          if(q.includes(keyword)) score += keyword.includes(" ") ? 12 : 8;
          else if(keyword.includes(q) && q.length >= 4) score += 6;
        });
        tokens.forEach(token=>{
          if(haystack.includes(token)) score += 3;
        });
        if(item.ja && String(query).includes(item.ja)) score += 40;
        if(item.kana && String(query).includes(item.kana)) score += 35;
        return {...item,score,index};
      }).sort((a,b)=>b.score-a.score || a.index-b.index);
    }


    function bab35GoogleSearchUrl(query){
      return `https://www.google.com/search?q=${encodeURIComponent(String(query || "").trim())}`;
    }

    function bab35WiktionaryPageUrl(term){
      return `https://ja.wiktionary.org/wiki/${encodeURIComponent(String(term || "").trim())}`;
    }

    function bab35StripMarkup(value=""){
      const holder = document.createElement("div");
      holder.innerHTML = String(value || "");
      return (holder.textContent || holder.innerText || "").replace(/\s+/g," ").trim();
    }

    async function bab35FetchJson(url,timeout=7000){
      const controller = typeof AbortController !== "undefined" ? new AbortController() : null;
      const timer = controller ? setTimeout(()=>controller.abort(),timeout) : null;
      try{
        const response = await fetch(url,{headers:{"Accept":"application/json"},signal:controller?.signal});
        if(!response.ok) throw new Error(`HTTP ${response.status}`);
        return await response.json();
      } finally {
        if(timer) clearTimeout(timer);
      }
    }

    async function bab35TranslateSituationToJapanese(query){
      const url = `https://api.mymemory.translated.net/get?q=${encodeURIComponent(String(query || "").slice(0,430))}&langpair=id|ja`;
      const data = await bab35FetchJson(url,6500);
      const translated = data?.responseData?.translatedText;
      return typeof translated === "string" ? translated.trim() : "";
    }

    function bab35JapaneseSearchTerms(translated="",localBest=null){
      const terms = [];
      if(localBest?.ja) terms.push(localBest.ja);
      let cleaned = String(translated || "")
        .replace(/[。！？!?]/g," ")
        .replace(/(しました|します|していました|しています|でした|です|だった|だと思います|と思います)$/g,"")
        .trim();
      if(cleaned) terms.push(cleaned);
      const chunks = cleaned.match(/[一-龯々〆ヵヶぁ-んァ-ヶー]{2,18}/g) || [];
      chunks.forEach(chunk=>{
        const short = chunk.replace(/(しました|します|でした|です|して|した|する|いる|ある|ます|たい|ない)$/g,"").trim();
        if(short.length >= 2) terms.push(short);
      });
      return [...new Set(terms.filter(Boolean))].slice(0,4);
    }

    async function bab35SearchJapaneseWiktionary(term){
      const url = `https://ja.wiktionary.org/w/api.php?action=query&list=search&srsearch=${encodeURIComponent(term)}&srlimit=6&srprop=snippet&format=json&formatversion=2&origin=*`;
      const data = await bab35FetchJson(url,6500);
      return (data?.query?.search || []).map(row=>({
        title:row.title,
        snippet:bab35StripMarkup(row.snippet || ""),
        source:"Wiktionary Jepang",
        url:bab35WiktionaryPageUrl(row.title)
      }));
    }

    async function bab35SearchJapaneseWikipedia(term){
      const q = `${term} ことわざ 慣用句`;
      const url = `https://ja.wikipedia.org/w/api.php?action=query&list=search&srsearch=${encodeURIComponent(q)}&srlimit=5&srprop=snippet&format=json&formatversion=2&origin=*`;
      const data = await bab35FetchJson(url,6500);
      return (data?.query?.search || []).map(row=>({
        title:row.title,
        snippet:bab35StripMarkup(row.snippet || ""),
        source:"Wikipedia Jepang",
        url:`https://ja.wikipedia.org/wiki/${encodeURIComponent(row.title)}`
      }));
    }

    function bab35RankWebCandidates(rows,searchTerms,localBest){
      const terms = (searchTerms || []).map(bab35NormalizeSituation).filter(Boolean);
      const markers = ["ことわざ","慣用句","成句","諺","格言","四字熟語","表現","言葉"];
      return rows.map((row,index)=>{
        const titleNorm = bab35NormalizeSituation(row.title);
        const textNorm = bab35NormalizeSituation(`${row.title} ${row.snippet}`);
        let score = 0;
        terms.forEach(term=>{
          if(titleNorm === term) score += 40;
          else if(titleNorm.includes(term) || term.includes(titleNorm)) score += 18;
          if(textNorm.includes(term)) score += 8;
        });
        markers.forEach(marker=>{ if(String(row.snippet || "").includes(marker)) score += 5; });
        if(localBest?.ja && row.title === localBest.ja) score += 55;
        return {...row,score,index};
      }).sort((a,b)=>b.score-a.score || a.index-b.index);
    }

    function bab35WebResultCard(row){
      return `<article class="kotowaza-result kotowaza-web-result">
        <span class="kotowaza-result-badge"><i class="fa-solid fa-globe"></i>${esc(row.source || "Sumber daring")}</span>
        <h4>${esc(row.title || "")}</h4>
        <div class="kotowaza-result-type"><i class="fa-solid fa-book"></i>Referensi yang mungkin cocok</div>
        <p>${esc(row.snippet || "Buka sumber untuk membaca penjelasan dan memastikan konteks penggunaannya.")}</p>
        <div class="kotowaza-result-actions">
          <a class="kotowaza-web-link wiktionary" href="${esc(row.url || bab35WiktionaryPageUrl(row.title))}" target="_blank" rel="noopener noreferrer"><i class="fa-solid fa-arrow-up-right-from-square"></i>Baca sumber</a>
          <a class="kotowaza-web-link google" href="${esc(bab35GoogleSearchUrl(`\"${row.title}\" ことわざ 慣用句 意味`))}" target="_blank" rel="noopener noreferrer"><i class="fa-brands fa-google"></i>Lihat di Google</a>
        </div>
      </article>`;
    }

    function bab35KotowazaResultCard(item,position=0){
      const sourceLabel = item.source === "Bab 35" ? "Dari materi Bab 35" : item.source === "Konteks tambahan" ? "Ungkapan terkait" : "Pepatah terkait";
      const typeLabel = item.expressionType || "Kotowaza";
      const searchTerm = item.ja || item.display || "";
      return `<article class="kotowaza-result">
        <span class="kotowaza-result-badge"><i class="fa-solid ${position===0?"fa-star":"fa-bookmark"}"></i>${esc(sourceLabel)}</span>
        <h4>${esc(item.display || item.ja)}</h4>
        <div class="reading jp">${esc(item.kana || "")}</div>
        <div class="reading">${esc(item.romaji || "")}</div>
        <div class="kotowaza-result-type"><i class="fa-solid fa-tag"></i>${esc(typeLabel)}</div>
        <div class="equivalent">${esc(item.idn || "")}</div>
        <p>${esc(item.situation || item.meaning || "")}</p>
        <div class="kotowaza-result-actions">
          <button type="button" data-direct-speak="${esc(searchTerm)}" data-direct-kind="vocab"><i class="fa-solid fa-volume-high"></i>Dengarkan</button>
          <a class="kotowaza-web-link google" href="${esc(bab35GoogleSearchUrl(`\"${searchTerm}\" ことわざ 慣用句 意味`))}" target="_blank" rel="noopener noreferrer"><i class="fa-brands fa-google"></i>Lihat di Google</a>
          <a class="kotowaza-web-link wiktionary" href="${esc(bab35WiktionaryPageUrl(searchTerm))}" target="_blank" rel="noopener noreferrer"><i class="fa-solid fa-book-open"></i>Buka Wiktionary</a>
        </div>
      </article>`;
    }

    async function renderBab35KotowazaSearch(query=""){
      const target = $("#kotowazaSearchResults");
      const status = $("#kotowazaOnlineStatus");
      const webTools = $("#kotowazaWebTools");
      if(!target) return;
      const q = String(query || "").trim();
      if(!q){
        target.innerHTML = `<div class="kotowaza-search-empty"><strong>Ceritakan situasimu.</strong> Misalnya: “jatuh cinta pada pandangan pertama”, “baru pindah dan belum betah”, “gagal ujian”, atau “harus memilih prioritas”.</div>`;
        if(status){ status.className="kotowaza-online-status"; status.innerHTML='<i class="fa-solid fa-circle-info"></i> Setelah kamu menekan <strong>Temukan Ungkapan yang Cocok</strong>, Wikaru akan mengecek koleksi dan referensi bahasa Jepang yang tersedia.'; }
        if(webTools) webTools.innerHTML = "";
        return;
      }

      const ranked = bab35RankKotowaza(q);
      const strong = ranked.filter(item=>item.score > 0).slice(0,3);
      const localBest = strong[0] || null;
      const fallbackIds = ["related-nanakorobi","related-isogaba","mnii-b35-ref-kotowaza-004"];
      const fallback = fallbackIds.map(id=>bab35KotowazaCorpus().find(item=>item.id===id)).filter(Boolean);
      const localResult = strong.length ? strong : fallback;
      const intro = strong.length
        ? `<div class="kotowaza-search-empty"><strong>Pilihan awal untuk:</strong> “${esc(q)}”. Hasil dari koleksi ditampilkan lebih dulu, lalu referensi bahasa Jepang diperiksa untuk membantu memastikan konteks.</div>`
        : `<div class="kotowaza-search-empty"><strong>Belum ada pilihan yang cukup dekat di koleksi untuk:</strong> “${esc(q)}”. Referensi bahasa Jepang akan diperiksa; sementara itu, berikut beberapa kotowaza umum yang mungkin membantu.</div>`;
      target.innerHTML = intro + localResult.map((item,index)=>bab35KotowazaResultCard(item,index)).join("");

      const initialGoogleQuery = localBest?.ja ? `\"${localBest.ja}\" ことわざ 慣用句 意味` : `${q} 日本語 ことわざ 慣用句 四字熟語`;
      if(webTools) webTools.innerHTML = `<a class="kotowaza-web-link google" href="${esc(bab35GoogleSearchUrl(initialGoogleQuery))}" target="_blank" rel="noopener noreferrer"><i class="fa-brands fa-google"></i>Lihat pencarian Google</a><a class="kotowaza-web-link wiktionary" href="https://ja.wiktionary.org/wiki/Special:Search?search=${encodeURIComponent(localBest?.ja || q)}" target="_blank" rel="noopener noreferrer"><i class="fa-solid fa-book-open"></i>Cari di Wiktionary Jepang</a>`;
      if(status){ status.className="kotowaza-online-status loading"; status.innerHTML='<i class="fa-solid fa-spinner fa-spin"></i> Mencari padanan Jepang dan memeriksa referensi bahasa Jepang…'; }

      try{
        let translated = "";
        try{ translated = await bab35TranslateSituationToJapanese(q); }catch(_e){ translated = ""; }
        const terms = bab35JapaneseSearchTerms(translated,localBest);
        const allRows = [];
        for(const term of terms.slice(0,2)){
          try{ allRows.push(...await bab35SearchJapaneseWiktionary(term)); }catch(_e){}
          if(allRows.length < 3){
            try{ allRows.push(...await bab35SearchJapaneseWikipedia(term)); }catch(_e){}
          }
        }
        const unique = [];
        const seen = new Set();
        allRows.forEach(row=>{
          const key = `${row.source}|${row.title}`;
          if(!seen.has(key)){ seen.add(key); unique.push(row); }
        });
        const webCandidates = bab35RankWebCandidates(unique,terms,localBest).filter(row=>row.score > 0).slice(0,3);
        if(webCandidates.length){
          const translatedNote = translated ? ` Terjemahan konteks: <span class="jp">${esc(translated)}</span>.` : "";
          target.insertAdjacentHTML("beforeend", `<div class="kotowaza-search-empty"><strong>Referensi tambahan dari sumber bahasa Jepang.</strong>${translatedNote} Baca penjelasan sumber untuk memastikan ungkapan tersebut benar-benar sesuai dengan situasimu.</div>${webCandidates.map(bab35WebResultCard).join("")}`);
          if(status){ status.className="kotowaza-online-status success"; status.innerHTML='<i class="fa-solid fa-circle-check"></i> Referensi daring sudah diperiksa. Jika situasimu lebih cocok dengan idiom atau ungkapan umum daripada kotowaza, halaman akan menampilkan bentuk yang lebih sesuai.'; }
        }else{
          if(status){ status.className="kotowaza-online-status warning"; status.innerHTML='<i class="fa-solid fa-triangle-exclamation"></i> Belum ditemukan referensi daring yang cukup jelas untuk ditampilkan sebagai rekomendasi. Gunakan pencarian Google di bawah untuk melihat pilihan lain dan membandingkan konteksnya.'; }
        }
        const googleQuery = localBest?.ja
          ? `\"${localBest.ja}\" ${translated || q} ことわざ 慣用句 意味`
          : `${translated || q} ことわざ 慣用句 四字熟語 意味`;
        if(webTools) webTools.innerHTML = `<a class="kotowaza-web-link google" href="${esc(bab35GoogleSearchUrl(googleQuery))}" target="_blank" rel="noopener noreferrer"><i class="fa-brands fa-google"></i>Lihat pencarian Google</a><a class="kotowaza-web-link wiktionary" href="https://ja.wiktionary.org/wiki/Special:Search?search=${encodeURIComponent(localBest?.ja || translated || q)}" target="_blank" rel="noopener noreferrer"><i class="fa-solid fa-book-open"></i>Cari di Wiktionary Jepang</a>`;
      }catch(_error){
        if(status){ status.className="kotowaza-online-status warning"; status.innerHTML='<i class="fa-solid fa-wifi"></i> Sumber daring sedang tidak dapat diakses. Pilihan dari koleksi tetap tersedia, dan pencarian Google masih dapat digunakan untuk pemeriksaan lanjutan.'; }
      }
    }

    function renderReferenceInfoBab35Kotowaza(){
      const grid = $("#materialGrid");
      if(!grid) return;
      const toolbar = $(".material-toolbar");
      const notice = $("#materialPage .notice");
      const title = $("#materialPage .content-card > h2");
      const desc = $("#materialPage .content-card > p");
      document.body.classList.add("material-only-reference","kotowaza-reference-active");
      if(toolbar){ toolbar.classList.add("hidden"); toolbar.style.setProperty("display","none","important"); toolbar.style.setProperty("visibility","hidden","important"); toolbar.style.setProperty("pointer-events","none","important"); }
      if(notice){ notice.classList.add("hidden"); notice.style.setProperty("display","none","important"); }
      if(title) title.textContent = state.lang === "ja" ? "第35課 ことわざ" : "Bab 35 — ことわざ / Pepatah Jepang";
      if(desc) desc.textContent = state.lang === "ja"
        ? "画像にある6つのことわざを、読み方・意味・インドネシア語の対応表現・使う場面から学びます。このカテゴリーにはクイズがありません。"
        : "Pelajari 6 kotowaza pada materi melalui cara baca, makna, padanan atau makna terdekat dalam bahasa Indonesia, contoh penggunaan, dan situasi pemakaiannya. Materi ini tidak masuk ke kuis.";

      const primaryCards = BAB35_REFERENCE_KOTOWAZA_ITEMS.map(item=>{
        const showBookEquivalent = item.bookEquivalent && item.bookEquivalent !== item.indonesia;
        const kanjiVariant = item.kanji && item.kanji !== item.displayTerm ? `<div class="kotowaza-book-equivalent"><strong>Bentuk kanji umum:</strong> ${esc(item.kanji)}</div>` : "";
        return `<article class="kotowaza-card">
          <div class="kotowaza-card-top"><span class="kotowaza-no">${esc(item.no)}</span><div><h4>${esc(item.displayTerm)}</h4><div class="kotowaza-kana jp">${esc(item.kana)}</div><div class="kotowaza-romaji">${esc(item.romaji)}</div>${kanjiVariant}</div></div>
          <div class="kotowaza-equivalent"><i class="fa-solid fa-language"></i> <strong>Padanan / makna dekat:</strong> ${esc(item.indonesia)}</div>
          ${showBookEquivalent ? `<div class="kotowaza-book-equivalent"><strong>Padanan pada gambar:</strong> ${esc(item.bookEquivalent)}</div>` : ""}
          <dl>
            <div><dt>Makna inti</dt><dd>${esc(item.literalMeaning)}</dd></div>
            <div><dt>Penjelasan</dt><dd>${esc(item.explanation)}</dd></div>
            <div><dt>Cocok dipakai saat</dt><dd>${esc(item.situation)}</dd></div>
            <div><dt>Contoh</dt><dd><span class="jp">${esc(item.exampleJa)}</span><br><small>${esc(item.exampleReading)}</small><br>${esc(item.exampleId)}</dd></div>
          </dl>
          <div class="kotowaza-actions"><button type="button" data-speak-id="${esc(item.id)}"><i class="fa-solid fa-volume-high"></i>Dengarkan pepatah</button></div>
        </article>`;
      }).join("");

      const relatedCards = BAB35_RELATED_KOTOWAZA.map(item=>`<article class="kotowaza-related-card">
        <h4>${esc(item.ja)}</h4><div class="kana jp">${esc(item.kana)} · ${esc(item.romaji)}</div>
        <div class="idn">${esc(item.idn)}</div><p>${esc(item.meaning)}</p>
        <div class="kotowaza-mini-actions"><button type="button" data-direct-speak="${esc(item.ja)}" data-direct-kind="vocab"><i class="fa-solid fa-volume-high"></i>Dengarkan</button></div>
      </article>`).join("");

      grid.className = "kotowaza-guide";
      grid.innerHTML = `
        <section class="kotowaza-hero">
          <div>
            <span class="kotowaza-eyebrow"><i class="fa-solid fa-book-open"></i> Minna no Nihongo II（第2版）• 第35課</span>
            <h3>ことわざ<span>Pepatah Jepang untuk berbagai situasi</span></h3>
            <p>Kenali bukan hanya artinya, tetapi juga gambaran, pesan, dan situasi ketika ungkapan itu digunakan. Bandingkan dengan ungkapan Indonesia yang maknanya dekat, lalu gunakan pencarian situasi untuk menemukan kotowaza atau ungkapan Jepang yang sesuai dengan konteks.</p>
            <div class="kotowaza-chip-row"><span class="kotowaza-chip"><i class="fa-solid fa-list"></i>${BAB35_REFERENCE_KOTOWAZA_ITEMS.length} pepatah utama</span><span class="kotowaza-chip"><i class="fa-solid fa-compass"></i>${BAB35_RELATED_KOTOWAZA.length} pepatah terkait</span><span class="kotowaza-chip"><i class="fa-solid fa-ban"></i>Tanpa kuis</span></div>
          </div>
          <figure class="kotowaza-cover"><button type="button" data-zoom="${esc(BAB35_REFERENCE_KOTOWAZA_IMAGE)}" aria-label="Perbesar poster ことわざ Bab 35"><img src="${esc(BAB35_REFERENCE_KOTOWAZA_IMAGE)}" alt="Poster berwarna ことわざ atau pepatah Jepang Bab 35" loading="eager" decoding="async" referrerpolicy="no-referrer" data-zoom="${esc(BAB35_REFERENCE_KOTOWAZA_IMAGE)}"></button><figcaption>Poster referensi Bab 35. Klik gambar untuk memperbesar.</figcaption></figure>
        </section>
        <aside class="kotowaza-note"><i class="fa-solid fa-circle-info"></i><div><strong>Padanan Indonesia tidak selalu harfiah</strong><p>Ungkapan Jepang dan Indonesia lahir dari latar budaya yang berbeda. Karena itu, padanan dipilih berdasarkan kemiripan pesan atau situasi. Jika tidak ada pepatah Indonesia yang benar-benar setara, halaman menampilkan makna yang paling dekat dan tetap mencantumkan padanan dari materi bila tersedia.</p></div></aside>
        <section class="kotowaza-section">
          <div class="kotowaza-section-head"><div><h3><i class="fa-solid fa-magnifying-glass"></i>Temukan Kotowaza atau Ungkapan Jepang dari Situasi</h3><p>Tulis situasimu dengan bahasa sehari-hari. Wikaru akan mencocokkannya dengan tema dan kata kunci pada koleksi, lalu memeriksa referensi bahasa Jepang yang tersedia. Jika kotowaza bukan pilihan yang paling tepat, hasil dapat berupa 慣用句, 四字熟語, atau ungkapan umum yang lebih sesuai.</p></div><span class="kotowaza-count">Koleksi + referensi daring</span></div>
          <div class="kotowaza-search-box">
            <div class="kotowaza-search-mode"><span><i class="fa-solid fa-database"></i>Koleksi Wikaru</span><span class="online"><i class="fa-solid fa-globe"></i>Referensi bahasa Jepang</span><span><i class="fa-solid fa-spell-check"></i>Utamakan ungkapan yang alami</span></div>
            <form class="kotowaza-search-form" id="kotowazaSituationForm"><input id="kotowazaSituationInput" type="search" autocomplete="off" placeholder="Contoh: Saya jatuh cinta pada pandangan pertama" aria-label="Tulis situasi untuk mencari kotowaza atau ungkapan Jepang"><button type="submit"><i class="fa-solid fa-magnifying-glass"></i> Temukan Ungkapan yang Cocok</button></form>
            <div class="kotowaza-suggestion-row">
              ${['jatuh cinta pada pandangan pertama','baru pindah dan belum betah','tim sedang mencari ide','gagal dan ingin bangkit lagi','terlalu khawatir sebelum memulai','harus fokus pada satu prioritas','mendapat rezeki tak terduga'].map(text=>`<button type="button" class="kotowaza-suggestion" data-kotowaza-suggestion="${esc(text)}">${esc(text)}</button>`).join("")}
            </div>
            <div id="kotowazaOnlineStatus" class="kotowaza-online-status" aria-live="polite"></div>
            <div class="kotowaza-search-results" id="kotowazaSearchResults" aria-live="polite"></div>
            <div id="kotowazaWebTools" class="kotowaza-web-tools"></div>
            <div class="kotowaza-privacy-note"><i class="fa-solid fa-shield-halved"></i><span>Untuk pencarian daring, teks situasi dikirim ke layanan terjemahan dan sumber kamus yang digunakan halaman ini. Jangan masukkan data pribadi atau informasi sensitif.</span></div>
          </div>
        </section>
        <section class="kotowaza-section"><div class="kotowaza-section-head"><div><h3><i class="fa-solid fa-book"></i>Enam Kotowaza dari Materi</h3><p>Urutan mengikuti poster referensi. Setiap kartu menampilkan cara baca, padanan atau makna terdekat dalam bahasa Indonesia, makna inti, penjelasan, situasi penggunaan, dan contoh kalimat.</p></div><span class="kotowaza-count">${BAB35_REFERENCE_KOTOWAZA_ITEMS.length} entri</span></div><div class="kotowaza-primary-grid">${primaryCards}</div></section>
        <section class="kotowaza-section"><div class="kotowaza-section-head"><div><h3><i class="fa-solid fa-layer-group"></i>Kotowaza Terkait</h3><p>Pilihan tambahan untuk memperluas kosakata dan membantu menemukan ungkapan yang cocok dengan situasi yang kamu tulis.</p></div><span class="kotowaza-count">${BAB35_RELATED_KOTOWAZA.length} tambahan</span></div><div class="kotowaza-related-grid">${relatedCards}</div><p class="kotowaza-footnote">Padanan bahasa Indonesia pada bagian ini dipilih berdasarkan kemiripan pesan. Tidak semua kotowaza memiliki pepatah Indonesia yang benar-benar setara.</p></section>
        <section class="kotowaza-section"><div class="kotowaza-section-head"><div><h3><i class="fa-solid fa-graduation-cap"></i>Cara Memahami Kotowaza dalam Konteks</h3><p>Tiga langkah sederhana agar kotowaza tidak hanya dihafal, tetapi juga dipahami kapan dan mengapa digunakan.</p></div></div><div class="kotowaza-learning-grid"><article class="kotowaza-learning-card"><span>1</span><h4>Baca gambaran literal</h4><p>Perhatikan benda, tindakan, atau perbandingan yang dipakai dalam pepatah.</p></article><article class="kotowaza-learning-card"><span>2</span><h4>Temukan pesan utamanya</h4><p>Tanyakan: pepatah ini sedang membahas usaha, kerja sama, adaptasi, kehati-hatian, atau hal lain?</p></article><article class="kotowaza-learning-card"><span>3</span><h4>Hubungkan dengan situasi nyata</h4><p>Cari satu kejadian yang pernah kamu alami. Hubungan dengan pengalaman membuat pepatah jauh lebih mudah diingat.</p></article></div></section>`;

      const form = $("#kotowazaSituationForm");
      const input = $("#kotowazaSituationInput");
      form?.addEventListener("submit",event=>{ event.preventDefault(); void renderBab35KotowazaSearch(input?.value || ""); });
      grid.querySelectorAll("[data-kotowaza-suggestion]").forEach(button=>button.addEventListener("click",()=>{
        if(input) input.value = button.dataset.kotowazaSuggestion || "";
        void renderBab35KotowazaSearch(button.dataset.kotowazaSuggestion || "");
        input?.focus();
      }));
      void renderBab35KotowazaSearch("");
      updateMaterialOnlyControls();
      if(typeof repairImages === "function") repairImages(grid);
    }


    function health36FormatTime(minutes){
      const m=((Math.round(minutes)%1440)+1440)%1440;
      const hh=String(Math.floor(m/60)).padStart(2,"0");
      const mm=String(m%60).padStart(2,"0");
      return `${hh}:${mm}`;
    }
    function health36TimeToMinutes(value="07:00"){
      const [h,m]=String(value||"07:00").split(":").map(Number);
      return (Number.isFinite(h)?h:7)*60+(Number.isFinite(m)?m:0);
    }
