      let activeFilter = "all";
      const applyFilter = ()=>{
        const q = String($("#useful41Search")?.value || "").trim().toLowerCase();
        let shown = 0;
        grid.querySelectorAll("[data-u41-card]").forEach(card=>{
          const matchesSection = activeFilter === "all" || card.dataset.section === activeFilter;
          const matchesQuery = !q || String(card.dataset.search || "").includes(q);
          const show = matchesSection && matchesQuery;
          card.classList.toggle("hidden", !show);
          if(show) shown++;
        });
        $("#useful41Empty")?.classList.toggle("hidden", shown > 0);
      };
      $("#useful41Search")?.addEventListener("input",applyFilter);
      grid.querySelectorAll("[data-u41-filter]").forEach(btn=>btn.addEventListener("click",()=>{
        activeFilter = btn.dataset.u41Filter || "all";
        grid.querySelectorAll("[data-u41-filter]").forEach(x=>x.classList.toggle("active",x===btn));
        applyFilter();
      }));
      grid.querySelectorAll("[data-u41-speak]").forEach(btn=>btn.addEventListener("click",()=>speak(btn.dataset.u41Speak || "","ja-JP")));
