    function installBasicProtection(){
      if(window.__wikaruProtectionInstalled) return;
      window.__wikaruProtectionInstalled = true;
      const protectedSelector = "#adminPage .table-wrap,#resultPage .table-wrap,#resultPage .review-list,#userDropdown,.password-shell,[data-inspect-private]";
      const markProtected = ()=>{
        $$(protectedSelector).forEach(el=>el.classList.add("inspect-private"));
      };
      const notifyBlocked = ()=>{
        document.body.classList.add("inspect-notice");
        try {
          if(window.WIKARU_INTERACTIONS?.showProtectionNotice) window.WIKARU_INTERACTIONS.showProtectionNotice();
          else toast(t("accessDisabled"));
        } catch(_) {}
        clearTimeout(window.__wikaruInspectNoticeTimer);
        window.__wikaruInspectNoticeTimer=setTimeout(()=>document.body.classList.remove("inspect-notice"),1500);
      };
      markProtected();
      document.addEventListener("dragstart",e=>{
        if(e.target instanceof HTMLImageElement) e.preventDefault();
      },{capture:true});

      const clearInspectionOverlay=()=>{
        document.body.classList.remove("inspect-private-mode");
        const overlay=$("#devtoolsOverlay");
        if(overlay){
          overlay.classList.remove("show");
          overlay.setAttribute("aria-hidden","true");
        }
        markProtected();
      };
      window.__wikaruClearInspectionOverlay=clearInspectionOverlay;
      window.addEventListener("pageshow",clearInspectionOverlay,{passive:true});
      window.addEventListener("resize",clearInspectionOverlay,{passive:true});
      document.addEventListener("visibilitychange",clearInspectionOverlay,{passive:true});

      clearInspectionOverlay();
    }

    function releaseLoadingScreen(reason="app-ready"){
      if(window.__wikaruLoaderFailsafe){
        clearTimeout(window.__wikaruLoaderFailsafe);
        window.__wikaruLoaderFailsafe = null;
      }
      if(typeof window.__wikaruReleaseLoader === "function"){
        window.__wikaruReleaseLoader(reason);
        return;
      }
      const loader=$("#loadingScreen");
      if(!loader) return;
      loader.classList.add("is-leaving");
      loader.style.pointerEvents="none";
      setTimeout(()=>{ loader.hidden = true; loader.classList.add("is-released"); loader.style.setProperty("display","none","important"); },520);
    }
    async function boot(){
      const absoluteFailsafe=setTimeout(()=>{ releaseLoadingScreen("boot-timeout"); try{ if(!state.setupCompleted && !$("#setupModal").classList.contains("show")) openSetup(); }catch(_){} },4300);
      let setupScheduled=false;
      try {
        wireEvents(); installBasicProtection();
        try { playTone("load"); } catch(_) {}


        applyTranslations(); renderAll();
        window.__wikaruCoreReady=true;
        document.documentElement.dataset.wikaruCoreReady="true";
        document.dispatchEvent(new CustomEvent("wikaru:core-ready"));
        const adminGroup=$("#adminGroup");
        if(adminGroup) adminGroup.innerHTML = `<option value="all">${state.lang==="ja"?"すべてのグループ":"Semua Grup"}</option>`;
        releaseLoadingScreen("ui-ready");
        setupScheduled=true;
        setTimeout(()=>{ try { if(!state.setupCompleted && !$("#setupModal").classList.contains("show")) openSetup(); } catch(_) {} },220);


        await Promise.resolve().then(()=>initSupabase()).catch(error=>{
          console.warn("Supabase initialization skipped:",error);
          return null;
        });
        if(cloudStatus().admin){
          state.session=storedAdminSession||{username:"admin404",group:"Admin",role:"admin",loggedAt:new Date().toISOString()};
          saveState();
        } else if(storedAdminSession){
          state.session=null;
          saveState();
        }
        if(state.session?.username && !isAdmin()){
          try { await Promise.race([loadUserLastResult(true),new Promise(resolve=>setTimeout(resolve,1600))]); } catch(_) {}
        }
        applyTranslations(); renderAll();
        if(adminGroup) adminGroup.innerHTML = `<option value="all">${state.lang==="ja"?"すべてのグループ":"Semua Grup"}</option>`;
      } catch(error){
        console.error("Wikaru boot recovery:",error);
        try { applyTranslations(); renderAll(); } catch(_) {}
      } finally {
        clearTimeout(absoluteFailsafe);
        releaseLoadingScreen("boot-complete");
        if(!setupScheduled){
          setTimeout(()=>{ try { if(!state.setupCompleted && !$("#setupModal").classList.contains("show")) openSetup(); } catch(_) {} },220);
        }
      }
    }

