  const escN=value=>String(value??"").replace(/[&<>"']/g,ch=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[ch]));
  const isJaN=()=>state?.lang==="ja";
  function isMinnaOne(book=""){ return /^Minna no Nihongo I(?:\s|$|\()/i.test(String(book||""))&&!/^Minna no Nihongo II/i.test(String(book||"")); }
  function isNumberSetup(setup=state?.setup){ return isMinnaOne(setup?.book)&&String(setup?.materialCategory||"")===NUMBER_CATEGORY&&String(setup?.chapter||"")===NUMBER_CHAPTER; }
  function isNumberActive(){ return isNumberSetup(state?.setup); }


  const previousCategoryLabelFor=categoryLabelFor;
  categoryLabelFor=function(value,lang=state.lang){
    const raw=String(value||"");
    if(raw===NUMBER_CATEGORY) return lang==="ja"?"付録一覧":"Daftar Lampiran";
    if(raw===NUMBER_CHAPTER) return lang==="ja"?"I. 数詞（すうし）":"I. Kata Bilangan";
    const jpMap={"Kata Bilangan":"数詞","Angka Dasar":"基本の数字","Angka 10–20":"10～20","Puluhan":"十の位","Ratusan":"百の位","Ribuan":"千の位","Bilangan Besar":"大きい数","Desimal":"小数","Pecahan":"分数"};
    if(lang==="ja"&&jpMap[raw]) return jpMap[raw];
    return previousCategoryLabelFor(value,lang);
  };

