  const markerSettings={mode:"numberToReading",groups:new Set(GROUP_ORDER),count:"20"};
  let markerQuiz=null;
  let markerRecognition=null;
  let markerSpeechTimer=0;
  let markerAutoNextTimer=0;
  let markerElapsedTimer=0;
