    const scored=COUNTER_GROUPS.map(g=>{
      const aliases=[g.titleId,g.titleJa,g.counter,...g.aliases].map(normalizeC);
      let score=0;aliases.forEach(a=>{if(!a)return;if(query===a)score=Math.max(score,100);else if(a.includes(query)||query.includes(a))score=Math.max(score,70-Math.abs(a.length-query.length));});
      return {g,score};
    }).filter(x=>x.score>0).sort((a,b)=>b.score-a.score);
    if(!scored.length){output.innerHTML=`<div class="counter-lab-placeholder"><i class="fa-solid fa-circle-question"></i>${isJaC()?'まだ登録されていません。別の物を試してください。':'Benda belum dikenali. Coba kata yang lebih umum, seperti “kertas”, “buku”, “mobil”, atau “ikan”.'}</div>`;return;}
    const group=scored[0].g;const sample=counterItem(group.key,3)||counterItem(group.key,1);
